pageCss:
.tc-code{background:#f4f6fa;border:1px solid #c8d2e2;border-left:3px solid #0831d9;padding:8px 10px;margin:0 0 12px;overflow-x:auto;font-size:9pt;line-height:1.5}
.tc-code code{white-space:pre}
.tc-demo{border:1px solid #9aa7ba;background:#eef1f6;margin:14px 0 16px;box-shadow:inset 1px 1px 0 #fff}
.tc-cols{display:grid;grid-template-columns:minmax(150px,1fr) minmax(0,1.5fr) minmax(0,1.5fr);gap:1px;background:#9aa7ba}
.tc-pick{background:#f6f8fb;padding:0 0 8px}
.tc-pick-head{font-family:var(--font-caption);font-size:8.5pt;text-transform:uppercase;letter-spacing:.06em;color:#4a5568;background:#e3e9f2;border-bottom:1px solid #c8d2e2;padding:5px 8px}
.tc-pick-head-2{margin-top:8px;border-top:1px solid #c8d2e2}
.tc-row{display:flex;align-items:flex-start;gap:6px;padding:4px 8px;font-size:8.5pt;line-height:1.35;cursor:pointer}
.tc-row:hover{background:#e8eefa}
.tc-row input{margin:2px 0 0;flex:0 0 auto}
.tc-row b{font-family:var(--font-mono);font-weight:normal;color:#123;display:block}
.tc-row span{color:#6b7688;display:block;font-size:8pt}
.tc-pane{background:#fff;min-width:0;display:flex;flex-direction:column}
.tc-pane-head{background:#e3e9f2;border-bottom:1px solid #c8d2e2;padding:4px 8px;font-size:8.5pt;color:#4a5568;display:flex;justify-content:space-between;align-items:center;gap:6px;min-height:26px}
.tc-dim{color:#8b95a6}
.tc-tabs{display:inline-flex;gap:4px}
.tc-tabs button{font:inherit;font-size:8pt;padding:1px 7px;border:1px solid #a9b4c6;background:linear-gradient(180deg,#fff,#e6eaf1);border-radius:3px;cursor:pointer;color:#33415c}
.tc-tabs button.on{background:linear-gradient(180deg,#cfe0fb,#a8c6f4);border-color:#5f86c8;color:#12305e;font-weight:bold}
.tc-src{margin:0;padding:8px 10px;font-size:8.5pt;line-height:1.45;overflow:auto;max-height:390px;flex:1}
.tc-src code{white-space:pre;font-family:var(--font-mono)}
.tc-legend{font-size:8.5pt;color:#5c6779;margin:0;padding:7px 10px;border-top:1px solid #c8d2e2;background:#f6f8fb}
.tc-scroll{overflow-x:auto;margin:0 0 12px}
.tc-table{border-collapse:collapse;font-size:8.5pt;width:100%;min-width:520px}
.tc-table th{text-align:left;background:#e3e9f2;border:1px solid #c8d2e2;padding:4px 7px;font-family:var(--font-caption);color:#33415c}
.tc-table td{border:1px solid #d8dfeb;padding:4px 7px;vertical-align:top}
.tc-table td code{font-size:8pt}
.tc-table tr:nth-child(even) td{background:#f8fafd}
.tc-ok{color:#1c6b32;font-weight:bold}
.tc-no{color:#a3261a;font-weight:bold}
.tc-mig td,.tc-bun td{line-height:1.5}
@media(max-width:760px){.tc-cols{grid-template-columns:1fr}.tc-src{max-height:250px}}

