// /garage/typed-config — the config explorer.
//
// Every row below was measured against a real Worker on wrangler 4.125.0 with
// @cloudflare/config 0.7.0: `resolved` is what `wrangler build --x-cf-build-output`
// wrote for that binding, and `env` is what tsc reported for that key of the
// generated interface. Nothing here is derived at runtime, so the page states
// measurements rather than guesses.
(function () {
  var BINDINGS = [
    { key: "RN_KV", note: "KV namespace", call: 'bindings.kv({ id: "3cb8a107c58e47dc9244e75b33401f36" })',
      resolved: { type: "kv", id: "3cb8a107c58e47dc9244e75b33401f36" }, env: "KVNamespace<string>", on: true },
    { key: "RESTORE_DB", note: "D1 database", call: 'bindings.d1({ id: "88c8daf1-3a36-4f8e-a2ad-dba8a74e1b9f", name: "aadhar-restore" })',
      resolved: { type: "d1", name: "aadhar-restore", id: "88c8daf1-3a36-4f8e-a2ad-dba8a74e1b9f" }, env: "D1Database", on: true },
    { key: "PHOTOS_R2", note: "R2 bucket", call: 'bindings.r2({ name: "aadhar-photos" })',
      resolved: { type: "r2", name: "aadhar-photos" }, env: "R2Bucket", on: true },
    { key: "AI", note: "Workers AI", call: "bindings.ai()", resolved: { type: "ai" }, env: "Ai<AiModels>", on: false },
    { key: "BROWSER", note: "Browser Run", call: "bindings.browser()", resolved: { type: "browser" }, env: "BrowserRun", on: false },
    { key: "BOT_LEDGER", note: "Analytics Engine", call: 'bindings.analyticsEngineDataset({ name: "aadhar_bot_ledger" })',
      resolved: { type: "analytics-engine-dataset", name: "aadhar_bot_ledger" }, env: "AnalyticsEngineDataset", on: false },
    { key: "CF_VERSION_METADATA", note: "version metadata", call: "bindings.versionMetadata()",
      resolved: { type: "version-metadata" }, env: "WorkerVersionMetadata", on: false },
    { key: "ASSETS", note: "static assets; the directory lives in wrangler.config.ts", call: "bindings.assets()",
      resolved: { type: "assets" }, env: "Fetcher", on: false },
    { key: "COUNTER", note: "Durable Object stub", call: 'bindings.durableObject({ workerName: "probe", exportName: "Counter" })',
      resolved: { type: "durable-object", workerName: "probe", exportName: "Counter" }, env: "DurableObjectNamespace<undefined>", on: true },
    { key: "SIGNING_SECRET", note: "secret; the value never enters the config", call: "bindings.secret()",
      resolved: { type: "secret" }, env: "string", on: true },
    { key: "AI_GATEWAY", note: "plain text; the value reaches the type", call: 'bindings.text("default")',
      resolved: { type: "text", value: "default" }, env: '"default"', on: true },
    { key: "FEATURES", note: "JSON; booleans narrow, numbers widen", call: "bindings.json({ dcz: true, tier: 2 })",
      resolved: { type: "json", value: { dcz: true, tier: 2 } }, env: "{ dcz: true; tier: number; }", on: true },
  ];

  var EXPORTS = [
    { key: "Counter", note: "created, SQLite storage", call: 'exports.durableObject({ storage: "sqlite" })',
      resolved: { type: "durable-object", storage: "sqlite" }, on: true },
    { key: "Legacy", note: "deleted; this destroys its stored data", call: 'exports.durableObject({ state: "deleted" })',
      resolved: { type: "durable-object", state: "deleted" }, on: false },
  ];

  var rows = document.getElementById("tc-rows");
  var rowsX = document.getElementById("tc-rows-x");
  var srcEl = document.getElementById("tc-src");
  var outEl = document.getElementById("tc-out");
  var table = document.getElementById("tc-table");
  if (!rows || !srcEl || !outEl) return;
  var mode = "resolved";

  function pick(list, host) {
    list.forEach(function (item) {
      var label = document.createElement("label");
      label.className = "tc-row";
      var box = document.createElement("input");
      box.type = "checkbox";
      box.checked = item.on;
      box.addEventListener("change", function () { item.on = box.checked; render(); });
      var text = document.createElement("span");
      var name = document.createElement("b");
      name.textContent = item.key;
      var note = document.createElement("span");
      note.textContent = item.note;
      text.appendChild(name);
      text.appendChild(note);
      label.appendChild(box);
      label.appendChild(text);
      host.appendChild(label);
    });
  }

  function chosen(list) { return list.filter(function (i) { return i.on; }); }

  function source() {
    var env = chosen(BINDINGS);
    var ex = chosen(EXPORTS);
    var lines = [];
    lines.push('import { bindings, defineWorker, exports, triggers } from "wrangler/experimental-config";');
    lines.push("");
    lines.push("export default defineWorker({");
    lines.push('  name: "probe",');
    lines.push('  compatibilityDate: "2026-08-15",');
    lines.push('  entrypoint: "./src/index.ts",');
    lines.push('  triggers: [triggers.fetch({ pattern: "aadhar.sh/probe/*", zone: "aadhar.sh" })],');
    if (env.length) {
      lines.push("  env: {");
      env.forEach(function (b) { lines.push("    " + b.key + ": " + b.call + ","); });
      lines.push("  },");
    }
    if (ex.length) {
      lines.push("  exports: {");
      ex.forEach(function (b) { lines.push("    " + b.key + ": " + b.call + ","); });
      lines.push("  },");
    }
    lines.push("});");
    return lines.join("\n");
  }

  function resolved() {
    var out = {
      type: "worker",
      name: "probe",
      compatibilityDate: "2026-08-15",
      triggers: [{ type: "fetch", pattern: "aadhar.sh/probe/*", zone: "aadhar.sh" }],
    };
    var env = chosen(BINDINGS);
    var ex = chosen(EXPORTS);
    if (env.length) {
      out.env = {};
      env.forEach(function (b) { out.env[b.key] = b.resolved; });
    }
    if (ex.length) {
      out.exports = {};
      ex.forEach(function (b) { out.exports[b.key] = b.resolved; });
    }
    return JSON.stringify(out, null, 2);
  }

  function envType() {
    var env = chosen(BINDINGS);
    if (!env.length) return "interface Env {}\n\n// No bindings selected, so env carries nothing\n// and every property read is a compile error.";
    var lines = ["interface Env {"];
    env.forEach(function (b) { lines.push("  " + b.key + ": " + b.env + ";"); });
    lines.push("}");
    return lines.join("\n");
  }

  function render() {
    srcEl.textContent = source();
    outEl.textContent = mode === "resolved" ? resolved() : envType();
  }

  var tabs = document.querySelectorAll(".tc-tabs button");
  Array.prototype.forEach.call(tabs, function (btn) {
    btn.addEventListener("click", function () {
      mode = btn.getAttribute("data-t");
      Array.prototype.forEach.call(tabs, function (b) { b.classList.toggle("on", b === btn); });
      render();
    });
  });

  if (table) {
    var head = document.createElement("tr");
    ["binding", "written as", "reaches the platform as", "env type"].forEach(function (h) {
      var th = document.createElement("th");
      th.textContent = h;
      head.appendChild(th);
    });
    table.appendChild(head);
    BINDINGS.forEach(function (b) {
      var tr = document.createElement("tr");
      [b.key, b.call, JSON.stringify(b.resolved), b.env].forEach(function (cell, i) {
        var td = document.createElement("td");
        var code = document.createElement("code");
        code.textContent = cell;
        td.appendChild(code);
        if (i === 3) td.className = "tc-envcell";
        tr.appendChild(td);
      });
      table.appendChild(tr);
    });
  }

  pick(BINDINGS, rows);
  if (rowsX) pick(EXPORTS, rowsX);
  render();
})();
